def use_in_anatomy_explorer(self):
    if self.busy or self.import_busy or not self.current or self.current.get('reference'):
        return
    mid=self.current['id'];name=self.current['name']
    self.import_busy=True;self.buttons();self.note.setText(f'Copying {name} into Anatomy Explorer…')
    def work():
        try:
            configuration=ROOT/'combined-app.json'
            if not configuration.is_file():
                raise RuntimeError('The combined app is not configured. Set its folder in combined-app.json, then try again.')
            combined=(ROOT/Path(json.loads(configuration.read_text(encoding='utf-8-sig'))['root']).expanduser()).resolve()
            settings=json.loads(configuration.read_text(encoding='utf-8-sig'))
            worktree=(ROOT/settings['worktree']).resolve() if settings.get('worktree') else combined/'application'
            python=(ROOT/settings['python']).resolve() if settings.get('python') else combined/'runtime/python.exe'
            script=worktree/'tools/import_refiner.py'
            if not python.is_file() or not script.is_file():
                raise RuntimeError('The combined app or its Python runtime is missing. Check the folder in combined-app.json or restore the combined app, then try again.')
            if not (ROOT/'library'/mid/'refined.npz').is_file():
                raise RuntimeError('This model has no saved refinement yet. Finish a refinement before importing its result.')
            if request('/api/models').get('running'):
                raise RuntimeError('A refinement is running. Wait for it to finish, then use this result.')
            completed=subprocess.run([str(python),str(script),'--refiner',str(ROOT),'--library',str(worktree/'data/local_model_library'),'--model',mid,'--post-only'],cwd=worktree,capture_output=True,text=True,encoding='utf-8',errors='replace',creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
            if completed.returncode:
                detail=(completed.stderr or completed.stdout or 'The importer returned an error.').strip()
                raise RuntimeError('Import failed. Your saved refinement remains available. '+detail[-1800:])
            return True,f'{name} copied into the active UI worktree. Close and reopen its model tab to load the saved result.'
        except Exception as exc:return False,str(exc)
    def finished(result):
        self.import_busy=False;self.buttons();success,message=result;self.note.setText(message)
        if not success:QMessageBox.warning(self,'Could not use this result',message)
    self.background(work,finished)
